const state = { buyerOrders: [], buyerEpoch: 0, buyerFilter: 'all', editorDraft: readEditorDraft(), user: null, stores: [], storeId: null, products: [], orders: [], movements: [], tab: initialRoute.get('compras') === '1' ? 'purchases' : 'overview', authMode: 'signin', notice: '', noticeType: '', error: '', loading: false, search: '', productFilter: 'all', orderFilter: 'active', epoch: 0, syncedAt: null, productRows: [], productEditing: null };
let authVersion = 0, toastTimer, modalReturnFocus, modalCleanup;
