const age = value => { const mins = Math.max(0, Math.round((Date.now() - new Date(value).valueOf()) / 60000)); return !Number.isFinite(mins) ? '' : mins < 1 ? 'agora' : mins < 60 ? `${mins} min` : mins < 1440 ? `${Math.floor(mins / 60)} h` : `${Math.floor(mins / 1440)} d`; };
