function ordersMarkup() {
 const activeStatuses = ['new','confirmed','packing','shipped'], done = state.orders.filter(order => state.orderFilter === 'completed' ? order.status === 'completed' : order.status === 'cancelled').sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));
 return `${pageHeading('Do pedido à próxima história.', 'Acompanhe cada etapa e mantenha sua operação em movimento.')}<div class="toolbar-row"><span class="queue-meta"><span class="status-dot"></span>Atualização automática a cada 30 segundos</span><select class="filter-select" id="order-filter" aria-label="Filtrar pedidos"><option value="active" ${state.orderFilter === 'active' ? 'selected' : ''}>Fila em andamento</option><option value="completed" ${state.orderFilter === 'completed' ? 'selected' : ''}>Concluídos</option><option value="cancelled" ${state.orderFilter === 'cancelled' ? 'selected' : ''}>Cancelados</option></select></div>${state.orderFilter === 'active' ? `<div class="queue-board">${activeStatuses.map(status => { const list = state.orders.filter(order => order.status === status); return `<section class="queue-column"><div class="queue-column-heading"><strong>${e(labels[status])}</strong><span>${list.length}</span></div>${list.length ? list.map(order => `<button class="order-card" data-order="${e(order.id)}"><span class="card-top"><strong>${e(orderNumber(order))}</strong><span>${e(age(order.created_at))}</span></span><h3>${e(order.customer_name || 'Cliente')}</h3><p>${itemsOf(order).reduce((sum,item) => sum + itemQty(item),0)} peça(s) · ${e(itemsOf(order).map(itemName).slice(0,2).join(', '))}</p><span class="card-bottom"><strong>${money(order.total_cents || 0)}</strong><span>Ver pedido ↗</span></span></button>`).join('') : '<div class="queue-empty">Tudo em dia por aqui.<br>Nenhum pedido nesta etapa.</div>'}</section>`; }).join('')}</div>` : `<section class="panel">${done.length ? `<div class="table-wrap"><table class="data-table"><thead><tr><th>Pedido</th><th>Cliente</th><th>Data</th><th>Total</th><th></th></tr></thead><tbody>${done.map(order => `<tr><td>${e(orderNumber(order))}</td><td>${e(order.customer_name)}</td><td class="nowrap muted">${e(date(order.created_at))}</td><td class="nowrap">${money(order.total_cents || 0)}</td><td><button class="text-button" data-order="${e(order.id)}">Ver detalhes ↗</button></td></tr>`).join('')}</tbody></table></div>` : empty('Nenhum pedido por aqui ainda.', `Quando houver pedidos ${state.orderFilter === 'completed' ? 'concluídos' : 'cancelados'}, você poderá consultá-los aqui.`, '', true)}</section>`}`;
}
function purchaseStore(order) { return Array.isArray(order.store) ? order.store[0] || null : order.store || null; }
function purchasesMarkup() {
 const all=state.buyerOrders,list=all.filter(order=>state.buyerFilter==='all'||(state.buyerFilter==='active'?!['completed','cancelled'].includes(order.status):order.status===state.buyerFilter));
 return `${pageHeading('Suas compras, de perto.', 'Acompanhe os pedidos feitos com a sua conta Camizetas.', '<a class="button secondary" href="lojas.html">Explorar lojas ↗</a>')}<div class="toolbar-row"><span class="quiet-note">${all.length} pedido${all.length===1?'':'s'} na sua conta</span><select class="filter-select" id="buyer-filter" aria-label="Filtrar minhas compras"><option value="all" ${state.buyerFilter==='all'?'selected':''}>Todas as compras</option><option value="active" ${state.buyerFilter==='active'?'selected':''}>Em andamento</option><option value="completed" ${state.buyerFilter==='completed'?'selected':''}>Concluídas</option><option value="cancelled" ${state.buyerFilter==='cancelled'?'selected':''}>Canceladas</option></select></div>${list.length?`<div class="purchase-list">${list.map(order=>{const store=purchaseStore(order),items=itemsOf(order);return `<article class="panel purchase-card"><div class="purchase-card-top"><div><span class="eyebrow">${e(store?.name||'Loja Camizetas')}</span><h2>Pedido ${e(orderNumber(order))}</h2><p>${e(date(order.created_at))}</p></div>${badge(order.status)}</div><div class="purchase-card-items">${items.slice(0,3).map(item=>`<p><strong>${itemQty(item)} × ${e(itemName(item))}</strong><span>${e([item.size,item.color].filter(Boolean).join(' · '))}</span></p>`).join('')}${items.length>3?`<p class="quiet-note">+ ${items.length-3} peça(s) no pedido</p>`:''}</div><div class="purchase-card-bottom"><strong>${money(order.total_cents||0)}</strong><div>${store?.slug?`<a class="text-button" href="loja.html?loja=${encodeURIComponent(store.slug)}" target="_blank" rel="noopener">Visitar loja ↗</a>`:''}<button class="button secondary small" data-purchase="${e(order.id)}">Detalhes do pedido ↗</button></div></div>${order.tracking_code?`<p class="purchase-tracking">Rastreamento: <strong>${e(order.tracking_code)}</strong></p>`:''}</article>`}).join('')}</div>`:`<section class="panel">${empty(all.length?'Nenhum pedido neste filtro.':'Sua próxima descoberta começa aqui.',all.length?'Escolha outro filtro para ver suas compras.':'Suas compras aparecerão aqui assim que você fizer um pedido em uma loja Camizetas.',!all.length?'<a class="button" href="lojas.html">Explorar marcas ↗</a>':'')}</section>`}`;
}
function openPurchase(id) {
 const order=state.buyerOrders.find(value=>value.id===id);if(!order)return;const store=purchaseStore(order),items=itemsOf(order),events=Array.isArray(order.events)?[...order.events].sort((a,b)=>new Date(a.created_at)-new Date(b.created_at)):[];
 openModal(`Sua compra ${orderNumber(order)}`,`${store?.name||'Loja Camizetas'} · ${date(order.created_at)}`,`<div class="modal-body"><div style="margin-bottom:23px">${badge(order.status)}</div><div class="details-grid"><div><p class="detail-label">Destinatário</p><p class="detail-value">${e(order.customer_name||'Cliente')}<br>${e(order.customer_phone||'')}</p></div><div><p class="detail-label">Endereço de entrega</p><p class="detail-value">${e(addressText(order.address))}</p></div>${order.tracking_code?`<div class="full"><p class="detail-label">Código de rastreamento</p><p class="detail-value">${e(order.tracking_code)}</p></div>`:''}${order.notes?`<div class="full"><p class="detail-label">Observações do pedido</p><p class="detail-value">${e(order.notes)}</p></div>`:''}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Peça comprada</th><th>Qtd.</th><th>Valor</th></tr></thead><tbody>${items.map(item=>`<tr><td>${e(itemName(item))}<br><span class="muted">${e([item.size,item.color].filter(Boolean).join(' · '))}</span></td><td>${itemQty(item)}</td><td class="nowrap">${money(Number(item.unit_price_cents||0)*itemQty(item))}</td></tr>`).join('')}</tbody></table></div><div class="order-total"><span>Total do pedido</span><strong>${money(order.total_cents||0)}</strong></div>${events.length?`<section class="purchase-events"><h3>Histórico do pedido</h3>${events.map(event=>`<p><span class="status-dot"></span><strong>${e(labels[event.status]||event.status||'Atualização')}</strong><small>${e(date(event.created_at))}</small></p>`).join('')}</section>`:''}<p class="quiet-note" style="margin:22px 0 0">A loja é responsável pelo preparo e envio. As informações da compra preservam as peças e valores registrados no pedido.</p></div><div class="modal-footer">${store?.slug?`<a class="button secondary" href="loja.html?loja=${encodeURIComponent(store.slug)}" target="_blank" rel="noopener">Visitar loja ↗</a>`:''}<button class="button" data-close>Fechar detalhes</button></div>`);
}
async function loadBuyerOrders({quiet=false}={}) {
 if(!state.user||state.tab!=='purchases')return;const epoch=++state.buyerEpoch,userId=state.user.id;if(!quiet){state.loading=true;state.error='';render()}
 try{const orders=await api.getBuyerOrders();if(epoch!==state.buyerEpoch||state.user?.id!==userId||state.tab!=='purchases')return;state.buyerOrders=(orders||[]).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));state.loading=false;state.error='';state.syncedAt=new Date();if(!quiet||!$('#modal')?.open)render()}catch(error){if(epoch!==state.buyerEpoch||state.user?.id!==userId||state.tab!=='purchases')return;state.loading=false;state.error=message(error);if(!quiet||!$('#modal')?.open)render()}
}
function settingsMarkup() {
 const store = currentStore();
 return `${pageHeading('Uma loja com a sua cara.', 'Sua identidade, seus dados e o próximo endereço da sua marca.')}<div class="settings-grid"><section class="panel"><div class="panel-heading"><h2>Dados e identidade da loja</h2><span>SEU UNIVERSO</span></div><form class="settings-form" id="settings-form">${state.editorDraft ? '<div class="editor-import-box"><strong>Seu estilo já tem um começo.</strong><p>Importe o template, as cores e a frase do rascunho deste navegador. Você pode revisar os campos antes de salvar na conta.</p><button type="button" class="button secondary small" id="import-editor-design">Importar estilo do editor ↙</button><p id="settings-import-feedback" role="status"></p></div>' : ''}<div class="form-grid"><label class="field full"><span>Nome da marca</span><input name="name" value="${e(store.name)}" required maxlength="60" autocomplete="organization"></label><label class="field full"><span>Endereço da loja</span><input name="slug" value="${e(store.slug)}" required minlength="3" maxlength="60" pattern="[a-z0-9]+(-[a-z0-9]+)*"><small>Alterar o endereço muda o link público da loja.</small></label><label class="field full"><span>Sobre sua marca</span><textarea name="description" maxlength="1000" rows="3" placeholder="Qual é a história por trás da sua marca?">${e(store.description || '')}</textarea></label><label class="field full"><span>Template</span><select name="template">${Object.entries(templateNames).map(([key,label]) => `<option value="${key}" ${key === store.template ? 'selected' : ''}>${e(label)}</option>`).join('')}</select></label><label class="field full"><span>Frase da coleção</span><textarea name="headline" maxlength="100" rows="2" placeholder="Uma frase com a sua personalidade">${e(store.headline || '')}</textarea></label><label class="field"><span>Cor de destaque</span><input type="color" name="accent" value="${/^#[0-9a-f]{6}$/i.test(store.accent) ? store.accent : '#6425d4'}"></label><label class="field"><span>Cor de fundo</span><input type="color" name="background" value="${/^#[0-9a-f]{6}$/i.test(store.background) ? store.background : '#faf9f6'}"></label></div><label class="check-field"><input type="checkbox" name="published" ${store.published ? 'checked' : ''}><span><strong>Publicar minha loja</strong><small>Uma loja publicada pode ser acessada por qualquer pessoa com o link. Revise seus produtos antes de ativar.</small></span></label><p class="inline-error" role="alert" id="settings-error"></p><div class="save-row"><button class="button" type="submit">Salvar alterações ↗</button><small>As configurações são salvas<br>na sua conta Camizetas.</small></div></form></section><aside class="panel"><div class="panel-body"><div class="theme-preview"><strong>${e(store.name)}</strong><span>Uma marca independente.</span><i aria-hidden="true">✳</i></div><h2 class="settings-card-title">Seu link, sua vitrine.</h2><p class="store-url">camizetas · <strong>${e(store.slug)}</strong></p><p class="settings-note">${store.published ? 'Sua loja está publicada. Compartilhe o endereço com quem tem tudo a ver com a sua marca.' : 'Sua loja está em rascunho. Ative a publicação quando estiver pronta para receber seus primeiros visitantes.'}</p><a class="button secondary" href="loja.html?loja=${encodeURIComponent(store.slug)}" target="_blank" rel="noopener">Abrir minha loja ↗</a><p class="settings-note" style="margin-top:22px"><strong>Operação com produtos próprios.</strong><br>Você cuida do estoque, do preparo e do envio. A produção sob demanda e o estúdio de IA estão em espera.</p></div></aside></div>`;
}
function render() {
 if(modalCleanup){modalCleanup();modalCleanup=null}
 if (!state.user || state.authMode === 'recovery') { $('#app').innerHTML = authMarkup(); bindAuth(); return; }
 if (state.tab === 'purchases') { $('#app').innerHTML = shell(state.loading ? '<div class="loading-line"><span class="spinner"></span>Buscando suas compras.</div>' : purchasesMarkup()); bindShell(); bindContent(); return; }
 if (!state.stores.length) { $('#app').innerHTML = shell(onboardingMarkup()); bindShell(); bindOnboarding(); return; }
 const content = state.loading ? '<div class="loading-line"><span class="spinner"></span>Buscando os dados da sua loja.</div>' : ({overview:overviewMarkup,products:productsMarkup,stock:stockMarkup,orders:ordersMarkup,settings:settingsMarkup}[state.tab] || overviewMarkup)();
 $('#app').innerHTML = shell(content); bindShell(); bindContent();
}
function bindAuth() {
 document.querySelectorAll('[data-auth]').forEach(button => button.onclick = () => { state.authMode = button.dataset.auth; notice(''); render(); });
 $('#recovery-signout')?.addEventListener('click', signOut);
 $('#auth-form').onsubmit = async event => { event.preventDefault(); const form = event.currentTarget; if (form.getAttribute('aria-busy') === 'true') return; const data = Object.fromEntries(new FormData(form)); busy(form,true); const mode = state.authMode; try {
  if (mode === 'reset') { await api.resetPassword(data.email.trim()); notice('Se este e-mail estiver cadastrado, você receberá um link para definir uma nova senha.','success'); render(); return; }
  if (mode === 'recovery') { if (typeof api.updatePassword !== 'function') throw new Error('A recuperação de senha ainda não está disponível.'); await api.updatePassword(data.password); state.authMode = 'signin'; await loadAuth(); toast('Sua senha foi atualizada.'); return; }
  if (mode === 'signup') { const result = await api.signUp(data.email.trim(),data.password); if (result?.needsConfirmation) { state.authMode = 'signin'; notice('Conta criada. Confira seu e-mail e confirme o cadastro antes de entrar.','success'); render(); return; } } else await api.signIn(data.email.trim(),data.password);
  notice(''); await loadAuth();
 } catch (error) { notice(message(error),'error'); render(); } finally { if (form.isConnected) busy(form,false); } };
}
function bindOnboarding() {
 const form = $('#store-form'); if (!form) return; let slugEdited = false; form.elements.slug.oninput = () => { slugEdited = true; }; form.elements.name.oninput = () => { if (!slugEdited) form.elements.slug.value = slugify(form.elements.name.value); };
 form.onsubmit = async event => { event.preventDefault(); if (form.getAttribute('aria-busy') === 'true') return; busy(form,true); const auth = state.user?.id, data = Object.fromEntries(new FormData(form)); try { const store = await api.createStore({name:data.name.trim(),slug:data.slug.trim()}); if (state.user?.id !== auth) return; state.stores = await api.getMyStores(); state.storeId = typeof store === 'string' ? store : store?.id || state.stores.at(-1)?.id; notice(''); state.tab=state.editorDraft?'settings':'overview'; await loadStore(); toast('Seu espaço está criado. Hora de dar vida à sua coleção.'); } catch (error) { if (state.user?.id === auth) { notice(message(error),'error'); render(); } } finally { if (form.isConnected) busy(form,false); } };
}
function bindShell() {
 document.querySelectorAll('[data-tab]').forEach(button => button.onclick = () => switchTab(button.dataset.tab));
 document.querySelectorAll('[data-refresh]').forEach(button => button.onclick = () => state.tab==='purchases'?loadBuyerOrders():state.storeId?loadStore():loadAuth());
 document.querySelectorAll('.signout').forEach(button => button.onclick = signOut);
 ['#store-switch','#mobile-store-switch'].forEach(selector => { const input = $(selector); if (input) input.onchange = () => { closeModal(); state.storeId = input.value; state.search=''; state.error=''; if(state.tab!=='purchases')loadStore(); }; });
 document.querySelectorAll('[data-new-store]').forEach(button => button.onclick = openNewStore);
 const dialog = $('#modal'); if (dialog) { dialog.addEventListener('click', event => { if (event.target === dialog) { const rect = dialog.getBoundingClientRect(); if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) closeModal(); } }); dialog.addEventListener('close', () => modalReturnFocus?.isConnected && modalReturnFocus.focus()); }
}
function bindContent() {
 document.querySelectorAll('[data-purchase]').forEach(button=>button.onclick=()=>openPurchase(button.dataset.purchase));
 if($('#buyer-filter'))$('#buyer-filter').onchange=event=>{state.buyerFilter=event.target.value;render()};
 document.querySelectorAll('[data-new-product]').forEach(button => button.onclick = () => openProduct());
 document.querySelectorAll('[data-edit-product]').forEach(button => button.onclick = () => openProduct(state.products.find(p => p.id === button.dataset.editProduct)));
 document.querySelectorAll('[data-product-stock]').forEach(button => button.onclick = () => { const product = state.products.find(p => p.id === button.dataset.productStock); state.tab='stock'; state.search=product?.name || ''; render(); });
 document.querySelectorAll('[data-stock]').forEach(button => button.onclick = () => openStock(button.dataset.stock));
 document.querySelectorAll('[data-order]').forEach(button => button.onclick = () => openOrder(button.dataset.order));
 if ($('#product-search')) $('#product-search').oninput = event => { state.search=event.target.value; $('#product-results').innerHTML=productRowsMarkup(); bindContentRows(); };
 if ($('#product-filter')) $('#product-filter').onchange = event => { state.productFilter=event.target.value; $('#product-results').innerHTML=productRowsMarkup(); bindContentRows(); };
 if ($('#stock-search')) $('#stock-search').oninput = event => { state.search=event.target.value; const variants=state.products.flatMap(product => (product.variants || []).map(variant => ({...variant,product}))), search=state.search.toLocaleLowerCase('pt-BR'); $('#stock-results').innerHTML=stockRowsMarkup(variants.filter(v => `${v.product.name} ${v.sku || ''} ${v.size || ''} ${v.color || ''}`.toLocaleLowerCase('pt-BR').includes(search)),variants); bindContentRows(); };
 if ($('#order-filter')) $('#order-filter').onchange = event => { state.orderFilter=event.target.value; render(); };
 if ($('#settings-form')) bindSettings();
}
function bindContentRows() { document.querySelectorAll('[data-new-product]').forEach(b => b.onclick=()=>openProduct()); document.querySelectorAll('[data-edit-product]').forEach(b => b.onclick=()=>openProduct(state.products.find(p=>p.id===b.dataset.editProduct))); document.querySelectorAll('[data-product-stock]').forEach(b=>b.onclick=()=>{state.tab='stock';state.search=state.products.find(p=>p.id===b.dataset.productStock)?.name||'';render()});document.querySelectorAll('[data-stock]').forEach(b=>b.onclick=()=>openStock(b.dataset.stock)); }
function switchTab(tab) { if (!icons[tab]) return; closeModal(); state.epoch++; state.buyerEpoch++; state.tab=tab; state.search=''; state.loading=false; state.error=''; if(tab==='purchases')loadBuyerOrders();else if(state.storeId)loadStore();else render(); window.scrollTo({top:0,behavior:'smooth'}); }
function openModal(title, subtitle, body, footer = '') { const modal=$('#modal'); if (!modal) return; if(modalCleanup){modalCleanup();modalCleanup=null} modalReturnFocus=document.activeElement; modal.innerHTML=`<div class="modal-header"><div><h2>${e(title)}</h2>${subtitle ? `<p>${e(subtitle)}</p>` : ''}</div><button class="modal-close" data-close aria-label="Fechar janela">×</button></div>${body}${footer}`; modal.querySelectorAll('[data-close]').forEach(button=>button.onclick=closeModal); modal.showModal(); }
function closeModal() { const modal=$('#modal'); if(modalCleanup){modalCleanup();modalCleanup=null} if (modal?.open) modal.close(); }
function openNewStore() { openModal('Um novo universo.', 'Cada marca pode ter seu próprio espaço.', `<form id="new-store-form"><div class="modal-body"><label class="field"><span>Nome da nova loja</span><input required name="name" maxlength="60" placeholder="O nome da sua próxima marca"></label><label class="field"><span>Endereço</span><input required name="slug" maxlength="60" minlength="3" pattern="[a-z0-9]+(-[a-z0-9]+)*" placeholder="minha-nova-marca"></label><p class="inline-error" role="alert"></p></div><div class="modal-footer"><button class="button secondary" type="button" data-close>Agora não</button><button class="button" type="submit">Criar loja ↗</button></div></form>`); const form=$('#new-store-form');let edited=false;form.elements.slug.oninput=()=>edited=true;form.elements.name.oninput=()=>{if(!edited)form.elements.slug.value=slugify(form.elements.name.value)};form.onsubmit=async event=>{event.preventDefault();if(form.getAttribute('aria-busy')==='true')return;busy(form,true);const userId=state.user?.id;try{const data=Object.fromEntries(new FormData(form)),created=await api.createStore({name:data.name.trim(),slug:data.slug.trim()});if(userId!==state.user?.id)return;state.stores=await api.getMyStores();state.storeId=typeof created==='string'?created:created?.id||state.stores.at(-1)?.id;closeModal();await loadStore();toast('Nova loja criada.')}catch(error){if(form.isConnected)form.querySelector('.inline-error').textContent=message(error)}finally{if(form.isConnected)busy(form,false)}}; }
function variantRowsMarkup() { return state.productRows.map((variant,index)=>`<div class="variant-row" data-row="${index}"><label><span>Tamanho</span><input name="size" value="${e(variant.size || '')}" maxlength="30" placeholder="M" required></label><label><span>Cor</span><input name="color" value="${e(variant.color || '')}" maxlength="50" placeholder="Preto" required></label><label><span>SKU</span><input name="sku" value="${e(variant.sku || '')}" maxlength="80" placeholder="Opcional"></label><label><span>${variant.id?'Disponível':'Estoque inicial'}</span><input type="number" name="on_hand" value="${Number(variant.on_hand || 0)}" min="0" max="1000000" step="1" required ${variant.id?'disabled':''}></label><button class="delete-variant" type="button" data-remove-variant="${index}" aria-label="Remover variação ${index+1}" ${variant.id?'disabled title="Variações existentes são preservadas para manter o histórico."':''}>×</button>${variant.id?'<p class="variant-exists">Para alterar o saldo desta variação, use a seção Estoque.</p>':''}</div>`).join(''); }
function syncVariantRows() { const rows=document.querySelectorAll('#variant-list .variant-row');rows.forEach((row,index)=>{const previous=state.productRows[index];if(!previous)return;for(const key of ['size','color','sku'])previous[key]=row.querySelector(`[name=${key}]`).value;if(!previous.id)previous.on_hand=Number(row.querySelector('[name=on_hand]').value)}); }
function bindVariantRows() { document.querySelectorAll('[data-remove-variant]').forEach(button=>button.onclick=()=>{syncVariantRows();const index=Number(button.dataset.removeVariant);if(state.productRows[index]?.id)return;if(state.productRows.length===1){$('#product-error').textContent='Mantenha pelo menos uma variação.';return}state.productRows.splice(index,1);$('#variant-list').innerHTML=variantRowsMarkup();bindVariantRows()}); }
function openProduct(product = null) {
 state.productEditing=product?.id || null;state.productRows=product?(product.variants || []).map(v=>({...v})):[{size:'Único',color:'Padrão',sku:'',on_hand:0}];if(!state.productRows.length)state.productRows=[{size:'Único',color:'Padrão',sku:'',on_hand:0}];
 openModal(product?'Ajuste sua peça.':'Sua próxima peça.',product?'Atualize o catálogo sem perder o histórico.':'Uma boa coleção começa com os detalhes certos.',`<form id="product-form"><div class="modal-body"><div class="form-grid"><label class="field full"><span>Nome do produto</span><input required name="name" maxlength="150" value="${e(product?.name || '')}" placeholder="Ex.: Camiseta essencial"></label><label class="field"><span>Preço de venda</span><input required name="price" inputmode="decimal" value="${product?(Number(product.price_cents)/100).toFixed(2).replace('.',','):''}" placeholder="89,90"></label><label class="field"><span>Categoria</span><select name="category">${categories.map(category=>`<option ${category===product?.category?'selected':''}>${e(category)}</option>`).join('')}</select></label><label class="field full"><span>Descrição</span><textarea name="description" rows="3" maxlength="3000" placeholder="Conte o que faz esta peça especial.">${e(product?.description || '')}</textarea></label><label class="field full"><span>Link da imagem <small style="display:inline">(opcional)</small></span><input type="url" name="image_url" value="${e(product?.image_url || '')}" maxlength="2000" placeholder="https://..."><small>Use um endereço público em HTTPS ou envie uma foto abaixo.</small></label><div class="field full"><span>Foto do produto</span><label class="product-file-upload">↥ Escolha uma foto da sua peça<input type="file" id="product-image-file" accept="image/jpeg,image/png,image/webp" aria-label="Enviar foto do produto JPG, PNG ou WebP até 5 MB"></label><small>A foto será enviada quando você salvar o produto. JPG, PNG ou WebP · até 5 MB.</small><div id="product-image-preview" class="product-file-preview" hidden><img alt="Prévia da foto selecionada"><span></span><button type="button" id="remove-product-image">Remover foto</button></div></div></div><div class="variant-heading"><h3>Tamanhos, cores e estoque</h3><button type="button" class="text-button" id="add-variant">+ Adicionar variação</button></div><div id="variant-list" class="variant-list">${variantRowsMarkup()}</div><p class="help-text">Cada combinação de tamanho e cor representa uma variação. O estoque é controlado separadamente para cada uma.</p><label class="check-field"><input type="checkbox" name="active" ${!product||product.active?'checked':''}><span><strong>Produto ativo no catálogo</strong><small>Produtos inativos ficam fora da vitrine, mas mantêm o histórico de pedidos.</small></span></label><p class="inline-error" role="alert" id="product-error"></p></div><div class="modal-footer"><button type="button" class="button secondary" data-close>Cancelar</button><button type="submit" class="button">${product?'Salvar alterações':'Cadastrar produto'} ↗</button></div></form>`);
 bindVariantRows();$('#add-variant').onclick=()=>{syncVariantRows();if(state.productRows.length>=50){$('#product-error').textContent='Você pode cadastrar até 50 variações por produto.';return}state.productRows.push({size:'',color:'',sku:'',on_hand:0});$('#variant-list').innerHTML=variantRowsMarkup();bindVariantRows();$('#variant-list .variant-row:last-child input').focus()};
 const form=$('#product-form'),epoch=state.epoch,storeId=state.storeId;
 let selectedImage=null,imageURL=null,imageVersion=0,imageReading=false;
 const fileInput=$('#product-image-file'),preview=$('#product-image-preview');
 const clearImage=()=>{imageVersion++;if(imageURL)URL.revokeObjectURL(imageURL);imageURL=null;selectedImage=null;imageReading=false;if(fileInput.isConnected)fileInput.value='';if(preview.isConnected){preview.hidden=true;preview.querySelector('img').removeAttribute('src')}};
 modalCleanup=clearImage;$('#modal').addEventListener('close',()=>{if(modalCleanup===clearImage){clearImage();modalCleanup=null}},{once:true});
 $('#remove-product-image').onclick=()=>{clearImage();$('#product-error').textContent=''};
 fileInput.onchange=()=>{const file=fileInput.files?.[0];if(!file)return;const version=++imageVersion;$('#product-error').textContent='';if(!['image/jpeg','image/png','image/webp'].includes(file.type)){clearImage();$('#product-error').textContent='Escolha uma foto JPG, PNG ou WebP.';return}if(!file.size||file.size>5*1024*1024){clearImage();$('#product-error').textContent='Escolha uma foto válida de até 5 MB.';return}imageReading=true;const candidate=URL.createObjectURL(file),image=new Image();image.onload=()=>{if(version!==imageVersion||!form.isConnected||!$('#modal')?.open){URL.revokeObjectURL(candidate);return}if(imageURL)URL.revokeObjectURL(imageURL);imageURL=candidate;selectedImage=file;imageReading=false;preview.hidden=false;preview.querySelector('img').src=candidate;preview.querySelector('span').textContent=`${file.name} · ${(file.size/1024/1024).toFixed(1)} MB · envio ao salvar`;};image.onerror=()=>{URL.revokeObjectURL(candidate);if(version!==imageVersion||!form.isConnected)return;clearImage();$('#product-error').textContent='Não foi possível abrir esta foto. Escolha outra imagem.';};image.src=candidate;};
 form.onsubmit=async event=>{event.preventDefault();if(form.getAttribute('aria-busy')==='true')return;if(imageReading){$('#product-error').textContent='Aguarde a leitura da foto antes de salvar.';return}busy(form,true);fileInput.disabled=true;$('#remove-product-image').disabled=true;$('#product-error').textContent='';try{syncVariantRows();const data=Object.fromEntries(new FormData(form)),image=data.image_url.trim();if(image&&(!safeImage(image)||!image.startsWith('https://')))throw new Error('Use um link de imagem que comece com https://.');const seen=new Set();const variants=state.productRows.map(variant=>{const size=variant.size.trim(),color=variant.color.trim(),key=`${size.toLowerCase()}|${color.toLowerCase()}`;if(!size||!color)throw new Error('Preencha tamanho e cor de todas as variações.');if(seen.has(key))throw new Error('Cada combinação de tamanho e cor deve ser única.');seen.add(key);if(!Number.isSafeInteger(Number(variant.on_hand))||variant.on_hand<0)throw new Error('O estoque inicial deve ser um número inteiro igual ou maior que zero.');return {...(variant.id?{id:variant.id}:{}),size,color,sku:variant.sku.trim(),on_hand:Number(variant.on_hand)}});const body={...(product?{id:product.id}:{}),name:data.name.trim(),description:data.description.trim(),category:data.category,image_url:image||null,price_cents:parsePrice(data.price),active:form.elements.active.checked};if(selectedImage){if(typeof api.uploadProductImage!=='function')throw new Error('O envio de fotos ainda não está disponível. Use um link HTTPS por enquanto.');const uploaded=await api.uploadProductImage(storeId,selectedImage);if(!sameContext(epoch,storeId)||!form.isConnected||!$('#modal')?.open)return;body.image_url=uploaded;form.elements.image_url.value=uploaded;}await api.saveProduct(storeId,body,variants);if(!sameContext(epoch,storeId))return;closeModal();await loadStore();toast(product?'Produto atualizado.':'Sua nova peça está no catálogo.')}catch(error){if(form.isConnected)$('#product-error').textContent=message(error)}finally{if(form.isConnected){busy(form,false);fileInput.disabled=false;$('#remove-product-image').disabled=false}}};
}
function findVariant(id) { for(const product of state.products){const variant=(product.variants||[]).find(v=>v.id===id);if(variant)return {product,variant}}return null; }
function openStock(id) {
 const found=findVariant(id);if(!found)return;const {product,variant}=found;
 openModal('Ajustar estoque.',`${product.name} · ${[variant.size,variant.color].filter(Boolean).join(' / ')}`,`<form id="stock-form"><div class="modal-body"><div class="notice inline">Disponível agora: <strong>${Number(variant.on_hand)} unidade(s)</strong>. Entradas somam ao saldo; saídas retiram peças do estoque.</div><div class="form-grid"><label class="field"><span>Tipo de ajuste</span><select name="direction"><option value="in">Entrada de peças</option><option value="out">Saída de peças</option></select></label><label class="field"><span>Quantidade</span><input name="quantity" type="number" required min="1" max="1000000" step="1" inputmode="numeric" placeholder="Ex.: 10"></label><label class="field full"><span>Motivo</span><textarea name="reason" required minlength="3" maxlength="300" rows="2" placeholder="Ex.: reposição de coleção, avaria ou conferência de estoque"></textarea></label></div><p class="inline-error" role="alert"></p></div><div class="modal-footer"><button type="button" class="button secondary" data-close>Cancelar</button><button type="submit" class="button">Confirmar ajuste ↗</button></div></form>`);
 const form=$('#stock-form'),epoch=state.epoch,storeId=state.storeId;form.onsubmit=async event=>{event.preventDefault();if(form.getAttribute('aria-busy')==='true')return;busy(form,true);try{const data=Object.fromEntries(new FormData(form)),qty=Number(data.quantity);if(!Number.isSafeInteger(qty)||qty<1)throw new Error('Informe uma quantidade inteira maior que zero.');if(data.reason.trim().length<3)throw new Error('Explique o motivo do ajuste.');await api.adjustStock(id,data.direction==='out'?-qty:qty,data.reason.trim());if(!sameContext(epoch,storeId))return;closeModal();await loadStore();toast('Estoque ajustado. A movimentação ficou registrada.')}catch(error){if(form.isConnected)form.querySelector('.inline-error').textContent=message(error)}finally{if(form.isConnected)busy(form,false)}};
}
function addressText(address) { if(typeof address==='string')return address;if(!address||typeof address!=='object')return 'Endereço não informado.';return [address.street||address.address||address.line1,address.number,address.complement||address.line2,address.neighborhood,[address.city,address.state].filter(Boolean).join(' / '),address.postal_code||address.zip||address.zipcode].filter(Boolean).join(' · ') || 'Endereço não informado.'; }
function openOrder(id) {
 const order=state.orders.find(item=>item.id===id);if(!order)return;const items=itemsOf(order),actions=nextStatuses(order.status),phone=String(order.customer_phone||'').replace(/\D/g,'');
 openModal(`Pedido ${orderNumber(order)}`,`Recebido em ${date(order.created_at)}`,`<div class="modal-body"><div style="margin-bottom:23px">${badge(order.status)}</div><div class="details-grid"><div><p class="detail-label">Cliente</p><p class="detail-value">${e(order.customer_name || 'Cliente')}<br>${phone?`<a href="tel:${e(phone)}">${e(order.customer_phone)}</a>`:'Telefone não informado.'}</p></div><div><p class="detail-label">Entrega</p><p class="detail-value">${e(addressText(order.address))}</p></div>${order.notes?`<div style="grid-column:1/-1"><p class="detail-label">Observações</p><p class="detail-value">${e(order.notes)}</p></div>`:''}${order.tracking_code?`<div style="grid-column:1/-1"><p class="detail-label">Rastreamento</p><p class="detail-value">${e(order.tracking_code)}</p></div>`:''}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Peça</th><th>Qtd.</th><th>Valor</th></tr></thead><tbody>${items.map(item=>`<tr><td>${e(itemName(item))}<br><span class="muted">${e([item.size,item.color].filter(Boolean).join(' · '))}</span></td><td>${itemQty(item)}</td><td class="nowrap">${money(Number(item.unit_price_cents||0)*itemQty(item))}</td></tr>`).join('')}</tbody></table></div><div class="order-total"><span>Total do pedido</span><strong>${money(order.total_cents||0)}</strong></div>${actions.length?`<section class="order-transition"><h3>Próxima etapa do pedido</h3>${actions.includes('shipped')?'<label class="field"><span>Código de rastreamento <small style="display:inline">(opcional)</small></span><input id="tracking-code" maxlength="120" placeholder="Informe o código de envio"></label>':''}<div class="transition-actions">${actions.filter(status=>status!=='cancelled').map(status=>`<button class="button" data-transition="${status}">${e(actionLabels[status])} ↗</button>`).join('')}</div>${actions.includes('cancelled')?'<label class="check-field cancel-check"><input type="checkbox" id="confirm-cancel"><span>Quero cancelar este pedido e devolver as peças ao estoque.</span></label><div class="transition-actions"><button class="button danger small" data-transition="cancelled" disabled>Cancelar pedido</button></div>':''}<p class="inline-error" role="alert" id="order-error"></p></section>`:`<p class="quiet-note" style="margin:22px 0 0">${order.status==='cancelled'?'Pedido cancelado. As peças foram devolvidas ao estoque.':'Este pedido já foi concluído.'}</p>`}</div><div class="modal-footer"><button class="button secondary" data-close>Fechar detalhes</button></div>`);
 const modal=$('#modal'),epoch=state.epoch,storeId=state.storeId;$('#confirm-cancel')?.addEventListener('change',event=>{modal.querySelector('[data-transition=cancelled]').disabled=!event.target.checked});modal.querySelectorAll('[data-transition]').forEach(button=>button.onclick=async()=>{if(modal.getAttribute('aria-busy')==='true')return;modal.setAttribute('aria-busy','true');modal.querySelectorAll('[data-transition]').forEach(b=>b.disabled=true);try{await api.transitionOrder(id,button.dataset.transition,$('#tracking-code')?.value.trim()||undefined);if(!sameContext(epoch,storeId))return;closeModal();await loadStore();toast(button.dataset.transition==='cancelled'?'Pedido cancelado e estoque devolvido.':'Pedido atualizado para a próxima etapa.')}catch(error){if(modal.isConnected&&modal.open){$('#order-error').textContent=message(error);modal.querySelectorAll('[data-transition]').forEach(b=>b.disabled=b.dataset.transition==='cancelled'&&!$('#confirm-cancel')?.checked)}}finally{modal.removeAttribute('aria-busy')}});
}
function bindSettings() {
 const form=$('#settings-form'),store=currentStore(),epoch=state.epoch,storeId=state.storeId;
 $('#import-editor-design')?.addEventListener('click',()=>{const draft=state.editorDraft;if(!draft)return;for(const key of ['template','accent','background','headline'])form.elements[key].value=draft[key];$('#settings-import-feedback').textContent='Estilo importado para os campos. Revise e clique em Salvar alterações para aplicar à loja.';form.elements.headline.focus()});
 form.onsubmit=async event=>{event.preventDefault();if(form.getAttribute('aria-busy')==='true')return;busy(form,true);$('#settings-error').textContent='';try{const data=Object.fromEntries(new FormData(form)),name=data.name.trim(),slug=data.slug.trim();if(!name)throw new Error('Informe o nome da sua marca.');if(!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug)||slug.length<3)throw new Error('Use pelo menos 3 letras minúsculas, números ou hífens no endereço.');const patch={name,slug,description:data.description.trim(),template:data.template,accent:data.accent,background:data.background,headline:data.headline.trim(),published:form.elements.published.checked};const updated=await api.updateStore(store.id,patch);if(!sameContext(epoch,storeId))return;state.stores=state.stores.map(s=>s.id===storeId?{...s,...patch,...updated}:s);render();toast('Sua loja foi atualizada.')}catch(error){if(form.isConnected)$('#settings-error').textContent=message(error)}finally{if(form.isConnected)busy(form,false)}};
}
async function loadStore({quiet=false}={}) {
 if(!state.user||!state.storeId)return;const epoch=++state.epoch,storeId=state.storeId;if(!quiet){state.loading=true;state.error='';render()}
 try{const [products,orders,movements]=await Promise.all([api.getProducts(storeId),api.getOrders(storeId),api.getInventoryMovements(storeId)]);if(!sameContext(epoch,storeId))return;state.products=products||[];state.orders=(orders||[]).sort((a,b)=>new Date(a.created_at)-new Date(b.created_at));state.movements=movements||[];state.syncedAt=new Date();state.error='';state.loading=false;if(!quiet||!$('#modal')?.open)render()}catch(error){if(!sameContext(epoch,storeId))return;state.loading=false;state.error=message(error);if(!quiet||!$('#modal')?.open)render()}
}
async function loadAuth() {
 const version=++authVersion;try{const user=await api.authUser();if(version!==authVersion)return;if(!user){state.user=null;state.stores=[];state.storeId=null;state.products=[];state.orders=[];state.movements=[];state.buyerOrders=[];state.buyerEpoch++;state.loading=false;state.epoch++;render();return}const sameUser=state.user?.id===user.id;if(!sameUser){state.products=[];state.orders=[];state.movements=[];state.buyerOrders=[];state.syncedAt=null;state.error='';state.buyerEpoch++}state.user=user;const stores=await api.getMyStores();if(version!==authVersion)return;state.stores=stores||[];if(!sameUser||!state.stores.some(s=>s.id===state.storeId))state.storeId=state.stores[0]?.id||null;if(state.authMode==='recovery'){render();return}if(state.tab==='purchases')await loadBuyerOrders();else if(state.storeId)await loadStore();else{state.loading=false;render()}}catch(error){if(version!==authVersion)return;notice(message(error),'error');state.error=message(error);state.loading=false;render()}
}
async function signOut() { try{await api.signOut();authVersion++;state.epoch++;state.user=null;state.stores=[];state.storeId=null;state.products=[];state.orders=[];state.movements=[];state.buyerOrders=[];state.buyerEpoch++;state.error='';state.authMode='signin';notice('');render()}catch(error){toast(message(error))} }

if (!api.ready) {
 $('#app').innerHTML=`<main class="initial-loading"><a class="brand" href="index.html">cami<span>z</span>etas®</a><section class="setup-card"><p class="eyebrow">PAINEL DA LOJA</p><h2>Seu espaço está sendo preparado.</h2><p>A conexão com o banco ainda não foi configurada. Volte em breve para criar sua conta e gerenciar a loja.</p><a class="button" href="index.html">Explorar a Camizetas ↗</a></section></main>`;
} else {
 api.onAuthChange((event,user)=>{ if(event==='PASSWORD_RECOVERY'){state.authMode='recovery';state.user=user||state.user;notice('');render();return}if(event==='TOKEN_REFRESHED')return;if(event==='SIGNED_OUT'){authVersion++;state.epoch++;state.user=null;state.stores=[];state.storeId=null;state.products=[];state.orders=[];state.movements=[];state.buyerOrders=[];state.buyerEpoch++;state.syncedAt=null;state.error='';state.loading=false;state.authMode='signin';notice('');render();return}setTimeout(()=>loadAuth(),0); });
 loadAuth();
 setInterval(()=>{if(state.user&&state.tab==='purchases'&&!document.hidden&&!$('#modal')?.open&&state.authMode!=='recovery'){loadBuyerOrders({quiet:true});return}if(state.user&&state.storeId&&['overview','orders','stock'].includes(state.tab)&&!document.hidden&&!$('#modal')?.open&&state.authMode!=='recovery')loadStore({quiet:true})},30000);
}
